with a as(select * from public.authors where open_library_id=any(array['OL863535A','OL934457A','OL709121A','OL1460559A','OL29079A','OL2660314A','OL74490A','OL7381348A','OL55662A']::text[]) or id=any(array[3341,379,746,678,3587]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789032004071','9789044914405','9789044332551','9789044915112','9789044912883','9789029071482','9789029016353','9789023472124','9789025452834']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL267613W','OL3899216W','OL15399488W','OL3899229W','OL3899217W','OL857601W','OL22755879W','OL33390812W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['asterixetlesnormands','asterixendenoormannen','mannensomgickuppirok','demandieinrookopging','crescentdawn','wassendemaan','polispolispotatismos','demandieevenwildeafrekenen','mannenpabalkongen','demanophetbalkon','laguerradelfindelmundo','deoorlogvanheteindevandewereld','metdekennisvantoen','inhetzwartvandespiegel']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['asterixetlesnormands','asterixendenoormannen','mannensomgickuppirok','demandieinrookopging','crescentdawn','wassendemaan','polispolispotatismos','demandieevenwildeafrekenen','mannenpabalkongen','demanophetbalkon','laguerradelfindelmundo','deoorlogvanheteindevandewereld','metdekennisvantoen','inhetzwartvandespiegel']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987108001 and 987108999),'editions',(select count(*) from public.editions where id between 987208001 and 987208999),'authors',(select count(*) from public.authors where id between 987308001 and 987308999))) as preflight;
